mapper.select:
SELECT count(id)
FROM gb_order_info
WHERE order_no = #{orderNo}

SELECT count(id)
FROM gb_order_info
WHERE group_id = #{groupId}

SELECT o.member_id AS memberId, MAX(o.mobile) AS mobile, MAX(o.nickname) AS nickname, MAX(o.avatar) AS avatar, COUNT(*) AS orderCount, SUM(o.pay_fee) AS totalPayFee, SUM(o.refund_fee) AS totalRefundFee, MAX(o.add_time) AS lastTime, ( SELECT group_name FROM gb_order_info WHERE leader_id = #{leaderId} AND member_id = o.member_id AND pay_time > 0 ORDER BY add_time DESC LIMIT 1 ) AS lastGroupName FROM gb_order_info o WHERE o.leader_id = #{leaderId} AND o.pay_time > 0
AND (o.mobile LIKE CONCAT('%', #{keyword}, '%') OR o.nickname LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY o.member_id ORDER BY lastTime DESC LIMIT #{offset}, #{pageSize}

SELECT

FROM gb_order_info
WHERE leader_id = #{leaderId}
  AND member_id = #{memberId}
  AND pay_time > 0
ORDER BY add_time DESC
